mapper.select:
SELECT id, outbound_order_id, authorization_id, attempt_id, xid, state, version
FROM outbound_execution_authorization
WHERE enterprise_id = #{enterpriseId} AND warehouse_id = #{warehouseId}
  AND client_operation_id = #{clientOperationId}

mapper.update:
UPDATE outbound_order
SET execution_authorization_id = #{authorizationId}, status = 'ALLOCATED', version = version + 1,
    updated_at = #{now}
WHERE enterprise_id = #{enterpriseId} AND warehouse_id = #{warehouseId} AND id = #{orderId}
  AND attempt_id IS NOT NULL
  AND (execution_authorization_id IS NULL OR execution_authorization_id = #{authorizationId})
